#!/usr/bin/env bash
# Question 1: Pods of api keep restarting. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "pay" >/dev/null 2>&1 || kubectl get namespace "pay" >/dev/null
timeout 60 bash -c "until kubectl -n 'pay' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api
  namespace: pay
  labels: { app: api }
spec:
  replicas: 0
  selector:
    matchLabels: { app: api }
  template:
    metadata:
      labels: { app: api }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
            limits: { cpu: 250m, memory: 128Mi }
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          livenessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
            failureThreshold: 2
EOF
kubectl -n "pay" get deployment "api" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"

case "${Q1_FAULT}" in
  liveness-port)
    kubectl -n "pay" patch deployment "api" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","livenessProbe":{"httpGet":{"path":"/","port":8080}}}]}}}}'
    ;;
  liveness-path)
    kubectl -n "pay" patch deployment "api" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","livenessProbe":{"httpGet":{"path":"/healthz","port":80}}}]}}}}'
    ;;
  liveness-exec)
    kubectl -n "pay" patch deployment "api" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/livenessProbe","value":{"exec":{"command":["cat","/tmp/healthy"]},"periodSeconds":5,"failureThreshold":2}}]'
    ;;
  liveness-early)
    kubectl -n "pay" patch deployment "api" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["/bin/sh","-c","sleep 20; exec nginx -g \"daemon off;\""],"livenessProbe":{"httpGet":{"path":"/","port":80},"initialDelaySeconds":2,"periodSeconds":3,"failureThreshold":2}}]}}}}'
    ;;
  oom-limit)
    kubectl -n "pay" set resources "deployment/api" -c web --requests=memory=4Mi --limits=memory=4Mi
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "pay" scale "deployment/api" --replicas=2
# What the learner must keep: the command and arguments as they are now, broken run or not.
kubectl -n "pay" get deployment "api" -o jsonpath='{.spec.template.spec.containers[0].command}|{.spec.template.spec.containers[0].args}' > "/var/tmp/cka-q1.cmd"
chmod 644 "/var/tmp/cka-q1.cmd"
for _ in $(seq 1 60); do
  [[ "$(kubectl -n "pay" get pods -l "app=api" -o jsonpath='{range .items[*]}{.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null | awk '{s+=$1} END {print s+0}')" -ge 1 ]] && exit 0
  sleep 3
done
echo "the Pods of api do not restart" >&2
exit 1
